{screen==="home"&&!manager&&<section className="rounded-[28px] border border-[#EADFD3] bg-white p-6 sm:p-8 space-y-5"><div className="flex flex-wrap justify-between items-start gap-3"><div><p className="text-sm tracking-[.16em] font-extrabold text-[#A55F12]">KEEP EXPLORING</p><h3 className="text-2xl font-extrabold mt-2">Your solar learning library ☀️</h3><p className="text-base text-[#6B6466] mt-2">Curious about solar in Kenya and beyond? Browse these trusted sources whenever you like. Optional reading—not another assignment.</p></div><span className="text-sm font-bold rounded-full bg-[#D3F2E2] text-[#00753E] px-3 py-2">4 USEFUL LINKS</span></div><div className="grid sm:grid-cols-2 gap-3">{solarResources.map(item=><a key={item.title} href={item.url} target="_blank" rel="noopener noreferrer" className="group rounded-2xl border border-[#EADFD3] p-5 hover:border-[#FAA954] hover:shadow-md transition-shadow space-y-2"><div className="flex items-center justify-between gap-3"><span style={{background:item.color}} className="rounded-full px-3 py-1 text-sm font-extrabold text-[#373435]">{item.tag}</span><span className="text-[#A55F12] font-black text-lg group-hover:translate-x-1 transition-transform">↗</span></div><h4 className="text-lg font-extrabold">{item.title}</h4><p className="text-base font-semibold text-[#A55F12]">{item.subtitle}</p><p className="text-base text-[#6B6466]">{item.detail}</p></a>)}</div><p className="text-sm text-[#6B6466]">For public-facing posts, check current facts and ask Brenda to approve content before publishing.</p></section>}
